from decimal import Decimal

from django.db import migrations

# Outflow limits for the school currencies added with the catalog (MYR, AUD, SGD), about the same as the existing
# ones (THB 50,000 / USD 1,500 per payment); daily is twice and monthly six times the per-payment limit.
LIMITS = {"MYR": Decimal("6500.00"), "AUD": Decimal("2300.00"), "SGD": Decimal("2000.00")}


def add_limits(apps, schema_editor):
    PolicyLimit = apps.get_model("finance", "PolicyLimit")
    for currency, single in LIMITS.items():
        PolicyLimit.objects.get_or_create(action="outflow", currency=currency, defaults={
            "per_transaction": single, "daily": single * 2, "monthly": single * 6, "enabled": True})


class Migration(migrations.Migration):

    dependencies = [
        ("finance", "0030_ledger_plan_bill"),
    ]

    operations = [
        migrations.RunPython(add_limits, migrations.RunPython.noop),
    ]
